async function api(url,opt={}){opt.headers={...(opt.headers||{}),'x-session':sid};let r=await fetch(url,opt);let j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'حدث خطأ');if(activeOverlay==='admin'&&String(opt.method||'GET').toUpperCase()!=='GET'){window.adminCacheValid=false;}return j}
