let rlLogoTaps=[];function bindSecretLogo(){const logo=document.getElementById('rlSecretLogo');if(!logo||logo.dataset.bound)return;logo.dataset.bound='1';const tap=()=>{const now=Date.now();rlLogoTaps=rlLogoTaps.filter(t=>now-t<2200);rlLogoTaps.push(now);if(rlLogoTaps.length>=5){rlLogoTaps=[];openSecretLogin();}};logo.addEventListener('click',tap);logo.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();tap();}});}
function openSecretLogin(){document.getElementById('rlSecretModal')?.classList.remove('hidden');}
