f.innerHTML=`<div class="rlPasswordRow rlGuestRow"><input id="ln" class="rlNameInput" autocomplete="nickname" placeholder="اكتب اسم الزائر (اسم فريد)" aria-label="اسم الزائر"><button type="button" class="primary guest" onclick="doGuest()">دخول</button></div>`;
