 window.rankDefinitions=Array.isArray(data.ranks)?data.ranks:[];RIMAZ_RANKS=window.rankDefinitions.slice().sort((a,b)=>Number(b.level)-Number(a.level)).map(r=>[r.id,(r.icon||'★')+' '+r.name]);
