async function modAction(action){const name=document.getElementById('modName')?.value,room=document.getElementById('modRoom')?.value||'public';if(!name)return toast('اكتب اسم المستخدم');const route=action==='unban'?'/api/admin/unban':action==='unmute'?'/api/admin/unmute':action==='kick'?'/api/admin/kick':action==='ban'?'/api/admin/ban':action==='mute'?'/api/admin/mute':'/api/admin/member-action';try{await api(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,room,action})});toast('تم تنفيذ الإجراء وحفظه');adminTab('moderation')}catch(e){toast(e.message)}}
