function callChoice(){if(!privateTo)return toast('اختر عضوًا أولًا');const layerEl=document.getElementById('layer');if(!layerEl)return;layerEl.insertAdjacentHTML('beforeend',`<div class="callChoice" id="callChoice"><div class="callChoiceBox"><h3>اختر نوع الاتصال</h3><button onclick="document.getElementById('callChoice')?.remove();startCall(false)">☎ اتصال صوتي</button><button onclick="document.getElementById('callChoice')?.remove();startCall(true)">📹 اتصال كام</button><button class="cancel" onclick="document.getElementById('callChoice')?.remove()">إلغاء</button></div></div>`)}
let pc=null,localStream=null,callMode='voice',callRemoteStream=null,callRemoteVideoStream=null,callRemoteAudioStream=null,callStatsTimer=null;const pendingCallIce=[],pendingOutgoingCallIce=[];let callPeerName='',callOfferSent=false,pendingIncomingCall=null,callFacingMode='user',callCameraSwitching=false;
async function getPrivateCallIceServers(){const fallback=[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun.cloudflare.com:3478'}];try{const config=await api('/api/rtc-config');return Array.isArray(config.iceServers)&&config.iceServers.length?config.iceServers:fallback}catch(error){console.warn('RTC configuration unavailable; using STUN fallback',error);return fallback}}
function setRemoteVideoStatus(message,visible=true){const status=document.getElementById('remoteVideoStatus');if(status){if(message)status.textContent=message;status.hidden=!visible}}
function playPrivateRemoteVideo(){const video=document.getElementById('remoteVideo');if(!video||!video.srcObject)return;video.muted=true;video.autoplay=true;video.playsInline=true;video.setAttribute('playsinline','');video.setAttribute('webkit-playsinline','');const result=video.play?.();if(result?.catch)result.catch(error=>console.warn('Private remote video playback deferred',error))}
function attachCallRemoteTrack(track){if(!track)return;if(track.kind==='video'){if(!callRemoteVideoStream)callRemoteVideoStream=new MediaStream();if(!callRemoteVideoStream.getTracks().some(t=>t.id===track.id))callRemoteVideoStream.addTrack(track);const video=document.getElementById('remoteVideo');if(video){if(video.srcObject!==callRemoteVideoStream)video.srcObject=callRemoteVideoStream;video.muted=true;video.autoplay=true;video.playsInline=true;video.onloadedmetadata=playPrivateRemoteVideo;video.oncanplay=playPrivateRemoteVideo}setRemoteVideoStatus('بانتظار صورة الطرف الآخر…',true);track.onunmute=()=>{setRemoteVideoStatus('',false);playPrivateRemoteVideo()};track.onmute=()=>setRemoteVideoStatus('الصورة متوقفة مؤقتاً…',true);track.onended=()=>setRemoteVideoStatus('انتهى إرسال صورة الطرف الآخر',true);if(!track.muted){setRemoteVideoStatus('',false);playPrivateRemoteVideo()}}else if(track.kind==='audio'){if(!callRemoteAudioStream)callRemoteAudioStream=new MediaStream();if(!callRemoteAudioStream.getTracks().some(t=>t.id===track.id))callRemoteAudioStream.addTrack(track);const audio=document.getElementById('remoteAudio');if(audio){if(audio.srcObject!==callRemoteAudioStream)audio.srcObject=callRemoteAudioStream;audio.autoplay=true;audio.playsInline=true;const play=audio.play?.();if(play?.catch)play.catch(error=>console.warn('Private remote audio playback deferred',error))}}const tracks=[...(callRemoteVideoStream?.getTracks()||[]),...(callRemoteAudioStream?.getTracks()||[])];callRemoteStream=tracks.length?new MediaStream(tracks):null}
function attachCallRemote(stream){if(!stream)return;for(const track of stream.getTracks())attachCallRemoteTrack(track)}
function startPrivateCallStats(){if(callStatsTimer)clearInterval(callStatsTimer);callStatsTimer=setInterval(async()=>{const active=pc;if(!active||callMode!=='camera'||active.connectionState==='closed')return;try{const report=await active.getStats(),rows=[],codecById=new Map(),transports=[];report.forEach(item=>{if(item.type==='codec')codecById.set(item.id,item.mimeType||item.codec||'unknown');if(item.type==='transport')transports.push({dtlsState:item.dtlsState,iceState:item.iceState,selectedCandidatePairId:item.selectedCandidatePairId})});report.forEach(item=>{if(item.type==='inbound-rtp'&&(item.kind==='video'||item.mediaType==='video'))rows.push({direction:'receive',packetsReceived:item.packetsReceived,bytesReceived:item.bytesReceived,framesReceived:item.framesReceived,framesDecoded:item.framesDecoded,framesPerSecond:item.framesPerSecond,frameWidth:item.frameWidth,frameHeight:item.frameHeight,framesDropped:item.framesDropped,codec:codecById.get(item.codecId)||item.codecId});if(item.type==='outbound-rtp'&&(item.kind==='video'||item.mediaType==='video'))rows.push({direction:'send',packetsSent:item.packetsSent,bytesSent:item.bytesSent,framesSent:item.framesSent,framesEncoded:item.framesEncoded,framesPerSecond:item.framesPerSecond,frameWidth:item.frameWidth,frameHeight:item.frameHeight,codec:codecById.get(item.codecId)||item.codecId})});const pairIds=transports.map(t=>t.selectedCandidatePairId).filter(Boolean);const pairs=[];report.forEach(item=>{if(item.type==='candidate-pair'&&pairIds.includes(item.id))pairs.push({state:item.state,nominated:item.nominated,currentRoundTripTime:item.currentRoundTripTime,availableOutgoingBitrate:item.availableOutgoingBitrate,localCandidateId:item.localCandidateId,remoteCandidateId:item.remoteCandidateId})});const localVideo=localStream?.getVideoTracks?.()[0];console.info('[Rimaz private video diagnostics]',{connection:active.connectionState,ice:active.iceConnectionState,signaling:active.signalingState,localTrack:localVideo?{enabled:localVideo.enabled,muted:localVideo.muted,readyState:localVideo.readyState,settings:localVideo.getSettings?.()}:null,transports,pairs,video:rows})}catch(error){console.warn('Private video stats unavailable',error)}},3000)}
function attachCallLocal(stream){const target=document.getElementById('localVideo');if(!target||!stream)return;target.srcObject=stream;target.classList.toggle('rearCamera',callFacingMode==='environment');const play=target.play?.();if(play?.catch)play.catch(()=>{})}
function addPrivateCallTracks(stream){if(!pc||!stream)throw new Error('اتصال الفيديو غير جاهز');for(const track of stream.getTracks()){const exists=pc.getSenders().some(sender=>sender.track?.id===track.id);if(!exists)pc.addTrack(track,stream)}}
function configureCallPeer(peerName,iceServers){callPeerName=peerName;callOfferSent=false;callRemoteStream=null;callRemoteVideoStream=null;callRemoteAudioStream=null;pc=new RTCPeerConnection({iceServers:iceServers||[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun.cloudflare.com:3478'}]});pc.onicecandidate=e=>{if(!e.candidate||!callPeerName)return;if(!callOfferSent)pendingOutgoingCallIce.push(e.candidate);else socket?.emit('ice',{to:callPeerName,candidate:e.candidate})};pc.ontrack=e=>{console.info('[Rimaz private call] remote track received',{kind:e.track.kind,id:e.track.id,muted:e.track.muted,readyState:e.track.readyState,streams:e.streams?.length||0});attachCallRemoteTrack(e.track)};pc.oniceconnectionstatechange=()=>console.info('[Rimaz private call] ICE state',pc?.iceConnectionState);pc.onsignalingstatechange=()=>console.info('[Rimaz private call] signaling state',pc?.signalingState);pc.onconnectionstatechange=()=>{console.info('[Rimaz private call] connection state',pc?.connectionState);if(pc&&['failed','closed'].includes(pc.connectionState))endCall(false)};if(callMode==='camera')startPrivateCallStats();return pc}
function flushOutgoingCallIce(){callOfferSent=true;while(pendingOutgoingCallIce.length){socket?.emit('ice',{to:callPeerName,candidate:pendingOutgoingCallIce.shift()})}}
async function flushCallIce(){if(!pc?.remoteDescription)return;while(pendingCallIce.length){const candidate=pendingCallIce.shift();try{await pc.addIceCandidate(candidate)}catch(error){console.warn('Private call ICE candidate failed',error)}}}
async function switchCallCamera(){
 if(callMode!=='camera'||!localStream||!pc||callCameraSwitching)return;
 if(!navigator.mediaDevices?.getUserMedia)return toast('المتصفح لا يدعم تبديل الكاميرا');
 const oldTrack=localStream.getVideoTracks()[0];
 if(!oldTrack)return toast('مسار الكاميرا غير متاح');
 const sender=pc.getSenders().find(item=>item.track?.kind==='video');
 if(!sender)return toast('مسار إرسال الفيديو غير جاهز');
 const oldSettings=oldTrack.getSettings?.()||{};
 const oldDeviceId=oldSettings.deviceId||'';
 const oldFacing=oldSettings.facingMode||callFacingMode||'user';
 const nextFacing=oldFacing==='environment'?'user':'environment';
 callCameraSwitching=true;
 const button=document.getElementById('switchCallCameraButton');
 if(button){button.disabled=true;button.textContent='جارٍ التبديل…'}
 let freshStream=null,oldTrackStopped=false;
 const stopFresh=()=>{if(freshStream){freshStream.getTracks().forEach(track=>track.stop());freshStream=null}};
 const rejectWrongCamera=(stream)=>{stream?.getTracks().forEach(track=>track.stop());const error=new Error('WRONG_CAMERA_SELECTED');error.name='OverconstrainedError';throw error};
 const validateCandidate=(stream,avoidId,direction)=>{
  const track=stream?.getVideoTracks?.()[0];
  if(!track){stream?.getTracks?.().forEach(item=>item.stop());const error=new Error('NO_VIDEO_TRACK');error.name='NotFoundError';throw error}
  const settings=track.getSettings?.()||{};
  if(avoidId&&settings.deviceId&&settings.deviceId===avoidId)rejectWrongCamera(stream);
  if(settings.facingMode&&settings.facingMode!==direction)rejectWrongCamera(stream);
  return stream;
 };
 const acquireFacing=async(direction,avoidId='')=>{
  const errors=[];
  let devices=[];
  try{devices=(await navigator.mediaDevices.enumerateDevices()).filter(device=>device.kind==='videoinput'&&device.deviceId)}catch(error){errors.push(error)}
  const isBack=direction==='environment';
  const labelPattern=isBack?/(back|rear|environment|world|خلف)/i:/(front|user|face|أمام)/i;
  const candidates=devices.filter(device=>device.deviceId!==avoidId&&labelPattern.test(device.label||''));
  for(const device of candidates){
   try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{deviceId:{exact:device.deviceId}}});
    return validateCandidate(stream,avoidId,direction);
   }catch(error){errors.push(error);console.warn('Camera device selection failed',error)}
  }
  // Use an exact facing-mode request when device labels are missing or unreliable.
  try{
   const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{exact:direction}}});
   return validateCandidate(stream,avoidId,direction);
  }catch(error){errors.push(error)}
  // Last fallback lets the browser select the requested direction, then verifies it did not return the old lens.
  try{
   const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:direction}}});
   return validateCandidate(stream,avoidId,direction);
  }catch(error){errors.push(error)}
  const hardwareBusy=errors.find(error=>['NotReadableError','TrackStartError'].includes(error?.name));
  throw hardwareBusy||errors[errors.length-1]||new Error('CAMERA_NOT_AVAILABLE');
 };
 try{
  try{freshStream=await acquireFacing(nextFacing,oldDeviceId)}
  catch(firstError){
   // A number of Android camera HALs expose one active camera at a time. Release the old capture only for that hardware-busy response.
   if(!['NotReadableError','TrackStartError'].includes(firstError?.name))throw firstError;
   oldTrack.stop();oldTrackStopped=true;
   await new Promise(resolve=>setTimeout(resolve,200));
   freshStream=await acquireFacing(nextFacing,oldDeviceId);
  }
  const nextTrack=freshStream.getVideoTracks()[0];
  await sender.replaceTrack(nextTrack);
  localStream.removeTrack(oldTrack);
  localStream.addTrack(nextTrack);
  freshStream.getTracks().filter(track=>track!==nextTrack).forEach(track=>track.stop());
  freshStream=null;
  if(!oldTrackStopped)oldTrack.stop();
  callFacingMode=nextFacing;
  attachCallLocal(localStream);
 }catch(error){
  stopFresh();
  console.error('Private-call camera switch failed',error);
  if(oldTrackStopped){
   try{
    let restoredStream=null;
    if(oldDeviceId){try{restoredStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{deviceId:{exact:oldDeviceId}}})}catch(restoreByIdError){console.warn('Restore by previous camera ID failed',restoreByIdError)}}
    if(!restoredStream)restoredStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:oldFacing}}});
    const restoredTrack=restoredStream.getVideoTracks()[0];
    if(!restoredTrack)throw new Error('ORIGINAL_CAMERA_RESTORE_FAILED');
    await sender.replaceTrack(restoredTrack);
    localStream.removeTrack(oldTrack);
    localStream.addTrack(restoredTrack);
    restoredStream.getTracks().filter(track=>track!==restoredTrack).forEach(track=>track.stop());
    callFacingMode=oldFacing;
    attachCallLocal(localStream);
   }catch(restoreError){console.error('Original camera restore failed',restoreError);toast('تعذر تبديل الكاميرا وتعذر استرجاع الكاميرا السابقة؛ أعد تشغيل الكاميرا')}
  }
  if(error?.name==='NotAllowedError'||error?.name==='SecurityError')toast('المتصفح منع الوصول للكاميرا؛ راجع إذن الكاميرا للموقع');
  else if(error?.name==='NotFoundError'||error?.name==='OverconstrainedError'||error?.message==='CAMERA_NOT_AVAILABLE'||error?.message==='WRONG_CAMERA_SELECTED')toast('لم يتم العثور على الكاميرا المطلوبة بهذا الاتجاه على الجهاز');
  else if(['NotReadableError','TrackStartError'].includes(error?.name))toast('الكاميرا مشغولة من تطبيق أو عملية أخرى؛ أغلق تطبيق الكاميرا وحاول مجدداً');
  else toast('تعذر تبديل الكاميرا؛ بقي الاتصال على الكاميرا السابقة');
 }finally{
  callCameraSwitching=false;
  if(button){button.disabled=false;button.textContent=callFacingMode==='environment'?'⇄ الكاميرا الأمامية':'⇄ الكاميرا الخلفية'}
 }
}

function incomingCallCard(d){const profile=d.fromProfile||{};const member={name:d.from,role:d.fromRole||'member',vip:!!d.fromVip,profile};return `<div class="incomingCallCard" id="incomingCallCard" role="dialog" aria-label="اتصال وارد"><div class="incomingCallTop"><b>${d.video?'📹 اتصال فيديو وارد':'☎ اتصال صوتي وارد'}</b><button type="button" onclick="rejectIncomingCall()" aria-label="إغلاق">×</button></div><div class="incomingCallIdentity"><img src="${esc(avatarFor(profile))}" alt=""><div><div class="incomingCallTitleLine"><span class="incomingCallRank">${memberBadge(member)}</span><strong>${esc(d.fromDisplayName||displayFor({name:d.from,profile})||d.from)}</strong></div><small>يتصل بك الآن</small></div></div><div class="incomingCallActions"><button class="acceptIncoming" onclick="acceptIncomingCall()">فتح الاتصال</button><button class="rejectIncoming" onclick="rejectIncomingCall()">إغلاق الاتصال</button></div></div>`}
async function startCall(camera){if(me.likes<500&&!me.admin)return toast('الاتصال يفتح عند 500 إعجاب');if(!privateTo)return toast('اختر عضوًا للاتصال');try{endCall(false,false);callMode=camera?'camera':'voice';callFacingMode='user';const iceServers=await getPrivateCallIceServers();configureCallPeer(privateTo,iceServers);showCall(camera,true);localStream=await navigator.mediaDevices.getUserMedia(camera?{audio:{echoCancellation:true,noiseSuppression:true},video:{facingMode:{ideal:'user'}}}:{audio:{echoCancellation:true,noiseSuppression:true},video:false});if(camera)attachCallLocal(localStream);addPrivateCallTracks(localStream);const offer=await pc.createOffer();await pc.setLocalDescription(offer);socket.emit('call-offer',{to:privateTo,offer,video:camera});flushOutgoingCallIce()}catch(error){console.error('Private call start failed',error);endCall(false,false);toast(error?.name==='NotAllowedError'?'اسمح للمتصفح باستخدام الكاميرا والمايك':'تعذر بدء الاتصال؛ تحقق من صلاحية الكاميرا والمايك')}}
function showCall(camera,outgoing=false){document.querySelector('.call')?.remove();document.getElementById('layer').insertAdjacentHTML('beforeend',`<div class="call ${camera?'cameraCall':'voiceCall'}">${camera?'<video id="remoteVideo" autoplay muted playsinline webkit-playsinline></video><audio id="remoteAudio" autoplay playsinline></audio><div id="remoteVideoStatus" class="remoteVideoStatus">بانتظار صورة الطرف الآخر…</div><video id="localVideo" class="localCallPreview" autoplay muted playsinline webkit-playsinline></video>':'<audio id="remoteAudio" autoplay playsinline></audio>'}<div class="callBar">${camera?'<button type="button" id="switchCallCameraButton" class="switchCallCamera" title="تبديل الكاميرا" aria-label="تبديل الكاميرا" onclick="switchCallCamera()">⇄ الكاميرا الخلفية</button>':''}<button onclick="endCall()">إنهاء الاتصال</button><button class="ok" onclick="document.querySelector('.call')?.classList.toggle('call-minimized')">${outgoing?'بانتظار الرد':(camera?'📹 اتصال فيديو':'☎ اتصال صوتي')}</button></div></div>`);if(camera&&localStream)attachCallLocal(localStream);if(callRemoteStream)attachCallRemote(callRemoteStream)}
function handleOffer(d){if(!d?.from)return;if(pc||pendingIncomingCall){socket?.emit('call-reject',{to:d.from,reason:'busy'});return}pendingIncomingCall=d;const layerEl=document.getElementById('layer');if(layerEl){document.getElementById('incomingCallCard')?.remove();layerEl.insertAdjacentHTML('beforeend',incomingCallCard(d))}else socket?.emit('call-reject',{to:d.from,reason:'unavailable'})}
async function acceptIncomingCall(){const incoming=pendingIncomingCall;if(!incoming)return;pendingIncomingCall=null;document.getElementById('incomingCallCard')?.remove();callMode=incoming.video?'camera':'voice';callFacingMode='user';try{const iceServers=await getPrivateCallIceServers();configureCallPeer(incoming.from,iceServers);showCall(!!incoming.video,false);localStream=await navigator.mediaDevices.getUserMedia(incoming.video?{audio:{echoCancellation:true,noiseSuppression:true},video:{facingMode:{ideal:'user'}}}:{audio:{echoCancellation:true,noiseSuppression:true},video:false});if(incoming.video)attachCallLocal(localStream);await pc.setRemoteDescription(incoming.offer);await flushCallIce();addPrivateCallTracks(localStream);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket.emit('call-answer',{to:incoming.from,answer,video:!!incoming.video});flushOutgoingCallIce()}catch(error){console.error('Private call acceptance failed',error);socket?.emit('call-reject',{to:incoming.from,reason:error?.name==='NotAllowedError'?'permission':'failed'});endCall(false,false);toast(error?.name==='NotAllowedError'?'لم تسمح باستخدام المايك أو الكاميرا':'تعذر قبول الاتصال؛ تحقق من صلاحية الجهاز')}}
function rejectIncomingCall(){const incoming=pendingIncomingCall;if(incoming)socket?.emit('call-reject',{to:incoming.from,reason:'declined'});pendingIncomingCall=null;pendingCallIce.length=0;document.getElementById('incomingCallCard')?.remove()}
async function handleAnswer(d){if(!pc||!d?.answer||key(d.from)!==key(callPeerName))return;try{await pc.setRemoteDescription(d.answer);await flushCallIce()}catch(error){console.warn('Private call answer setup failed',error);endCall();toast('تعذر إكمال الاتصال')}}
async function handleIce(d){if(!d?.candidate)return;if(!pc){if(pendingIncomingCall&&key(d.from)===key(pendingIncomingCall.from))pendingCallIce.push(d.candidate);return}if(key(d.from)!==key(callPeerName))return;if(!pc.remoteDescription){pendingCallIce.push(d.candidate);return}try{await pc.addIceCandidate(d.candidate)}catch(error){console.warn('Private call ICE candidate failed',error)}}
function endCall(showToast=true,notifyPeer=true){const peer=callPeerName;if(notifyPeer&&peer)socket?.emit('call-end',{to:peer});if(callStatsTimer){clearInterval(callStatsTimer);callStatsTimer=null}localStream?.getTracks().forEach(t=>t.stop());localStream=null;try{pc?.close()}catch{}pc=null;callRemoteStream=null;callRemoteVideoStream=null;callRemoteAudioStream=null;callPeerName='';callOfferSent=false;pendingCallIce.length=0;pendingOutgoingCallIce.length=0;document.querySelector('.call')?.remove();if(showToast)toast('تم إنهاء الاتصال')}
function clearIncomingCall(){pendingIncomingCall=null;pendingCallIce.length=0;document.getElementById('incomingCallCard')?.remove()}
window.addEventListener('beforeunload',()=>socket?.disconnect());
sid='';localStorage.removeItem('rimaz_sid');login();
